class NomVariableAuxiliarFormula extends BaseNomVariableAuxiliarFormula {
	
	/**
     * Obtener un listado de los datos de las variables auxiliares dado un identificador de concepto.
     * 
     * @param int $idconcepto  	Identificador de concepto.
     * @return array Listado de los datos de las variables auxiliares.
     */
    public static function obtenerListadoVariablesAuxiliares($idconcepto) {

        //Devolviendo el listado de variables auxiliares en forma de arreglo.
        return Doctrine_Query::create()
				->select('va.idvariableauxiliarformula, va.denominacion, va.idtipoentrada, te.denominacion as denomtipoentrada,
				va.idconfreportescertificaciones, rc.denominacion as denomreporte, 
				va.idvariablesconfreportescertificaciones, vrc.denominacion as denomvarreporte, va.idconceptopercepciondescuento')
				->from('NomVariableAuxiliarFormula va')
				->leftjoin('va.NomTipoEntrada te')
				->leftjoin('va.ConfReportesCertificaciones rc')
				->leftjoin('va.ConfVariablesReportesCertificaciones vrc')
                ->where('va.idconceptopercepciondescuento = ?', array($idconcepto))
                ->fetchArray();
    }
	
	/**
     * Obtener la variable auxiliar dado el identificador.
     * 
     * @param $idvarauxiliar        			Identificador de la variable auxiliar.
     * @return NomVariableAuxiliarFormula    	 Objeto variable auxiliar (clase del dominio).
     */
    public static function obtenerObjVariableAuxiliarDadoId($idvarauxiliar) {
        return Doctrine::getTable('NomVariableAuxiliarFormula')->find($idvarauxiliar);
    }
    
    public static function existeDenominacionVariableAuxiliar($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomVariableAuxiliarFormula p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 2;
		 }
     }
    
     public function obtenerVariablesPorArrConceptos($formaentrada = 2, $arrConceptosCoinciden = null){
		$imp = ($arrConceptosCoinciden ? " and v.idconceptopercepciondescuento in (".implode(',', $arrConceptosCoinciden).");" : "");
		$sql = "select v.idvariableauxiliarformula as id, v.idvariableauxiliarformula, v.denominacion, 3 as tipo, pd.idconceptopercepciondescuento, pd.denominacion as conceptopd from mod_nomina.nom_variableauxiliarformula v
					inner join mod_nomina.nom_conceptopercepciondescuento pd on (pd.idconceptopercepciondescuento = v.idconceptopercepciondescuento)
					where v.idtipoentrada = ?  {$imp}";

		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		return$conn->fetchAll($sql, array($formaentrada));
	}
}

     
   
    
    

